window.EB_SB_ADD({"sf2e-anachronism.guilt-of-the-grave-world-bestiary/LAIUEywNsyyCMRg4":{"notes":{"ac":"12 when broken"},"abilities":[{"n":"Construct Armor (Hardness 3)","a":null,"c":"defensive","t":[],"f":"","d":"<p>Like normal objects, the animated fire extinguisher has Hardness. This Hardness reduces any damage it takes by an amount equal to its Hardness. Once the animated fire extinguisher is reduced to less than half its Hit Points, or immediately upon being damaged by a critical hit, its construct armor breaks, removing its Hardness and reducing its Armor Class to 12.</p>"},{"n":"Auto-Fire","a":"2","c":"offensive","t":[],"f":"","d":"<p><strong>Foam Spray</strong> (20-foot cone, cold, magical)</p>\n<p><strong>Damage</strong> 1d8+2 cold (DC 15 basic Reflex)</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/iWP43xPPy9JVLhFr":{"lang":["Common","Eoxian","Necril"],"lore":[["Corpse Fleet Lore",4]],"gear":["Battleglove","Laser Pistol","Microcord Armor","Battery (Commercial) (2)"],"notes":{"hp":"void healing"},"abilities":[{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Quick Cover","a":"1","c":"offensive","t":[],"f":"","d":"<p>The bonecrusher Steps or Strides, then can Take cover as part of that same action if they end their movement adjacent to terrain that provides cover.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/1HDdV0YxZoA0trLs":{"lang":["Necril","can't speak any language"],"gear":["Integrated Advanced Machine Gun"],"abilities":[{"n":"Counter-fire","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> An enemy target attempts a ranged Strike against the boneflayer</p>\n<p><strong>Requirements</strong> The boneflayer is currently outside the melee reach of the enemy target</p><hr><p><strong>Effect</strong> The boneflayer attempts a ranged Strike. If the result of this Strike is equal to or greater than the result of the triggering Strike, the triggering Strike is treated as though it were a critical miss.</p>"},{"n":"Hypersonic Burst","a":"1","c":"offensive","t":[],"f":"once per minute","d":"<p><strong>Effect</strong> The boneflayer Steps or Strides twice.</p>"},{"n":"Rampage Strikes","a":"2","c":"offensive","t":[],"f":"","d":"<p>The boneflayer Steps or Strides, then makes two Strikes against the same target. Both Strikes count toward its multiple attack penalty, but its multiple attack penalty does not increase until after it makes both Strikes.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/pcvtftVSUWnuTsZ8":{"description":"<p>Smoldering boulders are disgorged by the magmatic soil and roll down the slope, catching fire as they descend.</p>","disable":"<p>DC 16 Nature (trained), DC 16 Physical science lore (trained), or DC 16 Survival (trained) to guess the rocks' path, or a DC 18 Acrobatics (trained), DC 18 Athletics (trained) or a DC 18 Fortitude save to deflect or dodge rocks.</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Catching Fire","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Creatures climb the slope</p><hr><p><strong>Effect</strong> Molten lava oozes down the slope, coming perilously close to the path and igniting the debris nearby—even the rocks. All creatures in a 30-foot burst take 1d10+4 bludgeoning plus 1d10+4 fire damage with a DC 16 basic Reflex save. On a critical failure the creature also catches on fire.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/J4QXF8oJlSMru16n":{"notes":{"per":"smoke vision"},"abilities":[{"n":"Smoke Vision","a":null,"c":"interaction","t":[],"f":"","d":"<p>The cinder ignores the Concealed condition from smoke.</p>"},{"n":"Hot Air","a":null,"c":"offensive","t":["aura","fire"],"f":"","d":"<p>5 feet. A creature that enters this aura or begins its turn there must succeed at a DC 22 Fortitude save or become Suppressed until the end of its next turn, as its feet (or similar appendages) burn.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/KiYitJyREH4Zjmd8":{"lang":["Common","Eoxian","Necril"],"lore":[["Corpse Fleet Lore",3]],"gear":["Reaction Breacher","Vertebralis Thorn","Defrex Hide","Projectile Ammo (36)","Battery (Commercial)"],"notes":{"hp":"void healing"},"abilities":[{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Fusillade","a":null,"c":"offensive","t":[],"f":"","d":"<p>The Corpse Fleet expendable's ranged Strikes deal an additional 1d4 precision damage when the Corpse Fleet expendable is within the first range increment of at least one other member of the Corpse Fleet wielding a ranged weapon.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/itxkgEs0mkwcxNhg":{"lang":["Common","Eoxian","Necril"],"lore":[["Corpse Fleet Lore",5]],"gear":["Semi-Auto Pistol","Tempweave","Datapad","Marrow Paste (Commercial)","Projectile Ammo (60)"],"notes":{"hp":"void healing"},"abilities":[{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Rally the Troops","a":"2","c":"offensive","t":["auditory","concentrate","mental"],"f":"","d":"<p>The officer issues an order for their allies to regroup. All Corpse Fleet allies within 120 feet of the officer can use a reaction to Stride up to their Speed. One Corpse Fleet ally who ends their movement adjacent to another Corpse Fleet ally gains 5 temporary Hit Points that last for 1 minute, or double that number of temporary Hit Points if they end their movement adjacent to the officer. The officer can't Rally the Troops again for 1d4 rounds.</p>\n<p>Effect: Rally the Troops</p>"},{"n":"Shoot to Kill","a":"1","c":"offensive","t":[],"f":"","d":"<p><strong>Frequency</strong> once per round</p><hr><p><strong>Effect</strong> The junior officer designates one target within 60 feet that they can see. That creature takes a –1 circumstance penalty to its AC against all ranged attacks made by members of the Corpse Fleet until the beginning of the Corpse Fleet junior officer's next turn.</p>\n<p>Effect: Shoot to Kill</p>"},{"n":"Startling Charge","a":"1","c":"offensive","t":[],"f":"","d":"<p><strong>Requirements</strong> An enemy creature is within 30 feet of the junior officer</p><hr><p><strong>Effect</strong> The junior officer twists their face into a horrific grimace before advancing. The junior officer attempts an Intimidation check to Demoralize the target creature, then Strides directly toward that creature.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/VN13DS4Ph4dhN9mu":{"description":"<p>The planetary shuttle has already taken severe damage to its engines and hull, sending it on a crash course toward the planet. Meanwhile, a necromantic spell planted in the ship's computer will imminently unleash an explosion of void energy.</p>","disable":"<p>DC 16 Piloting (trained) to take control and force the shuttle to a lower altitude, DC 18 Arcana (trained) or DC 18 Thievery (trained) to counter the necroblast long enough to prevent its detonation, DC 20 Perception to look for the closest landing zone, DC 20 Crafting (trained) to take apart the console and defuse the bomb, DC 23 Religion to pray for divine intercession; four total successes are required to defeat the hazard (see Development). A creature that succeeds at any of these checks gains a +1 circumstance bonus on their save against the hazard's damage for 1 round.</p>","reset":"<p>The bomb goes off after 4 rounds. See Development.</p>","routine":"<p>(3 actions) Void energy leaks out from the console as the necroblast prepares to detonate. All creatures on the ship take 2d6+4 void damage (DC 18 basic Will save).</p>","stealthNote":"<p>(trained) to notice necromantic energy emanating from the cockpit (allowing the use of Arcana to Disable).</p>","abilities":[{"n":"Final Countdown","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The encounter begins</p><hr><p><strong>Effect</strong> The necroblast begins its detonation countdown, and the doomed shuttle rolls initiative.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/LfdYQyHj3Jdnf52I":{"lang":["Pyric"],"notes":{"hp":"eruption","per":"smoke vision"},"abilities":[{"n":"Smoke Vision","a":null,"c":"interaction","t":[],"f":"","d":"<p>The drifting bonfire ignores the Concealed condition from smoke.</p>"},{"n":"Eruption","a":null,"c":"defensive","t":["fire"],"f":"","d":"<p>When the drifting bonfire is reduced to 0 HP, it erupts into a burst of lava, dealing 3d6 fire damage to each creature in a 10-foot emanation (DC 19 basic Reflex save).</p>"},{"n":"Residual Heat","a":"1","c":"offensive","t":["fire","primal"],"f":"","d":"<p><strong>Requirements</strong> The drifting bonfire's last action was a Strike that dealt damage</p><hr><p><strong>Effect</strong> The target of the Strike flares up, dealing 3d6 fire damage to each creature adjacent to the target (DC 19 basic Reflex save).</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/YtPDtjmBQq10pRl4":{"description":"<p>Electricity sparks from panels on the bridge. Wires leap out from access hatches in the corridors like wriggling snakes. The bridge is falling apart while Captain Concierge cheerfully offers helpful suggestions for how to fix the problem.</p>","disable":"<p>DC 17 Computers (trained) to reboot the system; DC 19 Crafting, DC 19 Physical science lore, or DC 19 Thievery (all trained) to flip circuit breakers and snip the correct wires; DC 21 Acrobatics, DC 21 Perception, or a DC 21 Reflex save to dodge the sparks; or DC 24 Athletics or a DC 24 Fortitude save to force the sparking panels closed. Disabling the trap removes one action from its routine for each successful check to disable it, or two actions on a critical success.</p>","reset":"<p>The exploding panels deactivate after 1 minute.</p>","routine":"<p>(3 actions) The exploding panels trap uses its actions to attack creatures inside the ship. It randomly slashes at creatures adjacent to bulkheads or sparks at creatures within 20 feet of any control surface. The trap does not take a multiple attack penalty.</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Cascading Failure","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The encounter begins</p><hr><p><strong>Effect</strong> Panels explode all over the ship with sparking live wires. All creatures on the ship take 2d8+5 electricity damage with a DC 21 basic Reflex save. The exploding panels then rolls for initiative.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/Mc2pC10GG2z13rOU":{"lang":["Common","Necril","Cannot speak"],"notes":{"hp":"void healing"},"flavor":"<p>The faceless are wisps of their former selves, virtually indistinguishable from any other ghost until they tear away their flesh-covered face and reveal the nothingness beneath. Their most noticeable feature is the disconcerting blank space with no ears, eyes, mouth, or nose located where their face should be.</p>\n<p>Faceless create masks using faces stolen from corpses or even the living, assuming a twisted version of the face's identity until the skin rots away, and they're forced to replace their grisly accessory.</p>\n<p>Left to their own devices, faceless undead float aimlessly, forlorn and hopeless, until they encounter a face and identity they can steal. Faceless are often drawn to carved or painted faces and sometimes attack other undead creatures.</p>\n<p>The Corpse Fleet recruits faceless undead to use as shock troops during boarding maneuvers. Some faceless embrace their identity as troopers, serving fearlessly and loyally until they inevitably lose control of themselves, violently tear through their own platoon, and have to be put down by their allies.</p><h2>Faceless Origins</h2><p>Nobody knows how faceless are created, but there are theories. Some theologians and scientists believe they're the husk left over after an undead creature's personality breaks down. Faceless don't recall their own origins, and their personalities grow more unstable every time they steal a new face. At least one infamous faceless assassin claimed to be an unidentified victim of a serial killer on Absalom Station. She was found with her face surgically removed and has been searching for a new one ever since.</p>","abilities":[{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Change Shape","a":"1","c":"offensive","t":["concentrate","polymorph"],"f":"","d":"<p>A faceless can take on the appearance of any Medium humanoid or undead in their collection of faces. This doesn't change their statistics.</p><hr><p><p>The monster changes its shape indefinitely. It can use this action again to return to its natural shape or adopt a new shape. Unless otherwise noted, a monster cannot use Change Shape to appear as a specific individual. Using Change Shape counts as creating a disguise for the Impersonate use of Deception. The monster's transformation automatically defeats Perception DCs to determine whether the creature is a member of the ancestry or creature type into which it transformed, and it gains a +4 status bonus to its Deception DC to prevent others from seeing through its disguise. Change Shape abilities specify what shapes the monster can adopt. The monster doesn't gain any special abilities of the new shape, only its physical form. For example, in each shape, it replaces its normal Speeds and Strikes, and might potentially change its senses or size. Any changes are listed in its stat block.</p></p>"},{"n":"Harvest Face","a":"3","c":"offensive","t":[],"f":"","d":"<p>The faceless tries to slice off the face of an adjacent dead or helpless target, stealing it for their grisly collection. The target must attempt a DC 18 Fortitude save. The faceless is Off-Guard until the beginning of their next turn.</p><hr><p><strong>Critical Success</strong> The target is unaffected.</p>\n<p><strong>Success</strong> The target takes 2d6 slashing damage and is Dazzled for 1 round.</p>\n<p><strong>Failure</strong> The target takes 5d6 slashing damage and is Blinded for 1 round. The creature's face is surgically removed and can only be restored with regenerate or a similar effect.</p>\n<p><strong>Critical Failure</strong> As failure, but the target takes 10d6 slashing damage.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/mxxkISfJoQJ8i8ms":{"lang":["Orbian","Telepathy 30 feet"],"notes":{"speed":"(hover)"},"abilities":[{"n":"Confusion","a":null,"c":"interaction","t":[],"f":"","d":"<p>Due to their confused state, the faltering green orbs take a –2 circumstance penalty to Intelligence-based checks.</p>"},{"n":"Mistvision","a":null,"c":"interaction","t":[],"f":"","d":"<p>A sapient orb always ignores Concealment caused by fog, smoke, and mist.</p>"},{"n":"Bitter Mist","a":"2","c":"offensive","t":[],"f":"once per minute","d":"<p><strong>Frequency</strong> once per minute</p><hr><p><strong>Effect</strong> The faltering green orb emits a green mist (as the spell) centered on itself. Sapient orbs can choose to emit transparent mist, granting no concealment. Additionally, any enemy in the mist when it appears, that enters the mist, or that ends its turn in the mist must attempt a DC 21 Will save unless they are Fascinated.</p><hr><p><strong>Critical Success</strong> The target is unaffected and becomes temporarily immune for 24 hours.</p>\n<p><strong>Success</strong> The target is unaffected.</p>\n<p><strong>Failure</strong> The target becomes Confused for 1 round.</p>\n<p><strong>Critical Failure</strong> The target becomes confused for 1 round, then Sickened 1.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/qSJT92ktGSjVvuAS":{"lang":["Common","Eoxian","Sarcesian","Sarcesian signed"],"lore":[["Piracy Lore",5]],"abilities":[{"n":"Compact Strides","a":null,"c":"interaction","t":[],"f":"","d":"<p>A sarcesian can move through spaces as though they were a Medium-sized creature.</p>"},{"n":"Stretchy Limbs","a":"1","c":"offensive","t":[],"f":"","d":"<p>The groggy corsair can adjust their gangly limbs to give themselves 10-foot reach until the start of their next turn.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/tNnp30Dsy4lwP1dY":{"abilities":[{"n":"Ambush","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature passes within 20 feet of the juvenile glass serpent and hasn't detected it</p><hr><p><strong>Effect</strong> The glass serpent lunges out of hiding. It Strides directly toward the triggering creature and makes a jaws Strike against it. The target creature is Off-Guard to this attack.</p>"},{"n":"Hostile Invisibility","a":null,"c":"defensive","t":[],"f":"","d":"<p>The juvenile glass serpent is naturally invisible. When a glass serpent takes a hostile action of any kind, it becomes visible until the start of its next turn, as its body becomes momentarily tangible. A glass serpent that has swallowed a creature becomes visible for the next day as its meal is digested. If the swallowed creature escapes or is otherwise removed, the glass serpent immediately returns to being invisible.</p>"},{"n":"Concealing Coil","a":"1","c":"offensive","t":[],"f":"","d":"<p><strong>Requirements</strong> The juvenile glass serpent's last action was a successful tail whip Strike</p><hr><p><strong>Effect</strong> The creature the glass serpent hit is Concealed from all creatures except the glass serpent until that creature moves out of the glass serpent's reach or until the start of the glass serpent's next turn.</p>"},{"n":"Swallow Whole","a":"1","c":"offensive","t":["attack"],"f":"","d":"<p>Medium, 1d8+4 bludgeoning, Rupture 9</p><hr><p><p>The monster attempts to swallow a creature of the listed size or smaller that it has grabbed or restrained in its jaws or mouth. If a swallowed creature is of the maximum size listed, the monster can't use Swallow Whole again. If the creature is smaller than the maximum, the monster can usually swallow more creatures; the GM determines the maximum. The monster attempts an Athletics vs. Reflex DC check opposed by the grabbed creature's Reflex DC. If it succeeds, it swallows the creature. The monster's mouth or jaws no longer grab a creature it has swallowed, so the monster is free to use them to Strike or Grab once again. The monster can't attack creatures it has swallowed.</p>\n<p>A swallowed creature is Grabbed, is Slowed 1, and has to hold its breath or start suffocating. The swallowed creature takes the listed amount of damage when first swallowed and at the end of each of its turns while it's swallowed. If the victim Escapes this ability's grabbed condition, it exits through the monster's mouth. This frees any other creature grabbed in the monster's mouth or jaws. A swallowed creature can attack the monster that has swallowed it, but only with unarmed attacks or with weapons of light Bulk or less. The swallowing creature is Off-Guard against the attack. If the monster takes piercing or slashing damage equaling or exceeding the listed Rupture value from a single attack or spell, the swallowed creature cuts itself free. A creature that gets free by either Escaping or cutting itself free can immediately breathe and exits the swallowing monster's space.</p>\n<p>Effect: Engulf and Swallow Whole</p>\n<p>If the monster dies, a swallowed creature can be freed by creatures adjacent to the corpse if they spend a combined total of 3 actions cutting the monster open with a weapon or unarmed attack that deals piercing or slashing damage.</p></p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/nPSciVswzRhnBCCZ":{"abilities":[{"n":"Bristle Flash","a":"1","c":"offensive","t":["light","visual"],"f":"","d":"<p>The tashtari causes its filaments to glow with intense light. Non-tashtaris within a 40-foot emanation must attempt a DC 19 Fortitude save. The tashtari's fur then dims, and they can't use this ability until they bask in sunlight for at least 10 minutes.</p><hr><p><strong>Critical Success</strong> The creature is unaffected.</p>\n<p><strong>Success</strong> The creature is Dazzled for 1 round.</p>\n<p><strong>Failure</strong> The creature is dazzled for 1 minute.</p>\n<p><strong>Critical Failure</strong> The creature is Blinded for 1 round and dazzled for 1 minute.</p>"},{"n":"Knockdown","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Knockdown in its damage entry</p><hr><p><strong>Effect</strong> The monster attempts to Trip the creature. This attempt neither applies nor counts toward the monster's multiple attack penalty.</p></p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/T3m2zy7JAl8boymY":{"gear":["Fire Shield"],"notes":{"hp":"fiery vitality, void healing"},"abilities":[{"n":"Shield Block","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> The monster has its shield raised and takes damage from a physical attack.</p>\n<hr>\n<p><strong>Effect</strong> The monster snaps its shield into place to deflect a blow. The shield prevents the monster from taking an amount of damage up to the shield's Hardness. The monster and the shield each take any remaining damage, possibly breaking or destroying the shield.</p></p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Fiery Vitality","a":"f","c":"offensive","t":[],"f":"once per round","d":"<p><strong>Effect</strong> Any time Kitthaine uses a spell or ability with the fire trait, they regain 7 healing Hit Points (to a maximum of their total HP).</p>"},{"n":"Fire Shield","a":"2","c":"offensive","t":["fire"],"f":"","d":"<p>Kitthaine raises a fiery barrier around them, granting them a +1 circumstance bonus to AC until the end of their next turn. While this ability is in effect, they can use the Shield Block reaction as if the fire shield was a raised shield. The shield has Hardness 6 against all sources of damage, but this increases by 4 against fire damage. Unlike a normal Shield Block, Kitthaine can also use this reaction against effects with the fire trait.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/Bof81QpbW3jmHZYc":{"notes":{"hp":"void healing"},"abilities":[{"n":"Life Blindness","a":null,"c":"defensive","t":[],"f":"","d":"<p>A lifeleech ooze can only detect living and undead creatures. It has no other sensory abilities. When injured by vitality damage, a lifeleech ooze's senses are overwhelmed, and it automatically becomes Blinded until the end of its next turn.</p>"},{"n":"Share Space","a":null,"c":"defensive","t":[],"f":"","d":"<p>A lifeleech ooze can share the space of up to four medium or smaller creatures without squeezing, so long as it has room to retain its original shape.</p>"},{"n":"Strip Flesh","a":null,"c":"defensive","t":[],"f":"","d":"<p>Any living creature that begins its turn sharing the same space as a lifeleech ooze takes 3d6 void damage, with a DC 24 basic Fortitude save.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/izCx1cFDZP6lQcAf":{"description":"<p>Pebbles and boulders broken off from Barrow's crust accelerate all around the space between the Fracture and the surface, smashing into anything and everything!</p>","disable":"<p>DC 20 Acrobatics to avoid impact, DC 23 Athletics or Strike (AC 20) to break or deflect incoming debris</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Impact","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature fails its check to disable or avoid the hazard</p><hr><p><strong>Effect</strong> Micrometeors slam into the target, dealing 2d10+13 bludgeoning damage and potentially knocking them off course based on a DC 21 Reflex save.</p><hr><p><strong>Critical Success</strong> The creature takes no damage.</p>\n<p><strong>Success</strong> The creature takes half damage.</p>\n<p><strong>Failure</strong> The creature takes full damage and gains the Untethered condition, which persists until the start of the next encounter.</p>\n<p><strong>Critical Failure</strong> As failure, but the creature takes double damage.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/IsuQst3MOBDEspty":{"description":"<p>Four mortar tubes are constantly being auto-loaded by robotic arms before swiveling to launch projectiles onto the nearby battlefield.</p>","disable":"<p>DC 16 Warfare lore to engage the mortar safety switches, DC 18 Thievery to jam the auto-loading mechanisms so no more ammunition can be cycled, or DC 20 Athletics to push the tubes out of alignment such that the projectiles no longer threaten the battlefield</p>","reset":"<p>The hazard resets automatically. Any time a PC leaves the trenches, they're targeted by Exploding Ordinance until the mortar shells hazard is disabled.</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Exploding Ordinance","a":"r","c":"defensive","t":["fire"],"f":"","d":"<p><strong>Trigger</strong> A creature fails its check to disable the mortar shells hazard</p><hr><p><strong>Effect</strong> A mortar shell explodes, dealing 2d10 fire damage in a 10-foot burst centered on a corner of the triggering creature's square with a DC 18 basic Reflex save.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/T9uucuCG6UFWZLOB":{"notes":{"hp":"void healing"},"flavor":"<p>The Corpse Fleet's most overt long-term goal is establishing the supremacy of undeath in the Pact Worlds solar system, with the system's new immortal overlords eradicating or enslaving the living as they see fit. Eventually, the glorious Corpse Fleet hopes to conquer all of Desna's Path, and perhaps expand to other galaxies.</p>\n<p>On the smaller scale of operations, Corpse Fleet researchers experiment with necromantic weapons of all kinds, including unliving biological weapons like mummy wasps.</p>\n<p>Mummy wasps are created by fumigating wasp swarms inside of their hives and then painstakingly and individually mummifying them in sacred paper wrappings before burying and reviving the whole nest in an unholy ritual.</p>\n<p>When deployed, mummy wasps viciously attack living creatures and ignore undead, making them an ideal weapon for zone control and enemy suppression.</p>\n<p>They're also incredibly aggressive and invasive. Mummy wasps have been spotted in locations far from the Corpse Fleet facilities in the Vast where they were created.</p>\n<p>Mummy wasp nests have been deployed at Barrow and other Corpse Fleet installations. They're also utilized as ammunition, shot out of breaching cannons or hurled from vehicles.</p><h2>Dangerous Research</h2><p>The successful engineering of mummy wasps and rigor mortics has emboldened devious Corpse Fleet scientists to push the boundaries even further and create more powerful unliving weapons. Intelligence from the few Steward spies inside the Corpse Fleet indicates that the admiralty is ready to launch Project Gravemind, an effort to convert Swarm components into undead troopers. Succeed or fail, the consequences of such an experiment could be disastrous for the Pact Worlds.</p>","abilities":[{"n":"Mummy Storm","a":null,"c":"defensive","t":["aura","divine","emotion","fear","incapacitation","mental"],"f":"","d":"<p>Millions of enchanted paper shreds orbit the swarm in a 10-foot emanation. Creatures inside this aura gain greater cover from the attacks of creatures outside of it. Any living creature that enters the aura or begins its turn inside it must succeed at a DC 22 Will save or become Frightened 1.</p>"},{"n":"Rejuvenation","a":null,"c":"defensive","t":["divine"],"f":"","d":"<p>When a mummy wasp swarm is destroyed, the hive's necromantic energies reanimate a new swarm over 1d6 days. A reforming mummy wasp swarm is destroyed permanently if its hive is consecrated or destroyed (30 HP) with vitality, water, or fire damage.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Unliving Stings","a":"1","c":"offensive","t":[],"f":"","d":"<p>Each creature in the swarm's space takes 2d10 void damage (DC 24 basic Reflex save). A creature that fails its save additionally takes 2d6 persistent void damage (double damage on a critical failure).</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/4XHrKB4GP5e6I9uH":{"description":"<p>A gigantic spinal column, ripped whole from a great beast, is posed on the surface of Barrow, enhanced with necromantic technology that turns it into a unliving weapons system. Its skull has been replaced with sensor arrays and deadly ice beam emitters.</p>","disable":"<p>DC 16 Computers (trained) or DC 16 Vidgame lore (trained) to shut down the necroturret's tech targeting system, DC 18 Arcana (trained), DC 18 Nature (trained), DC 18 Occultism (trained), or DC 18 Religion (trained) to disrupt the necroturret's magical core, or DC 20 Athletics or DC 20 Thievery to destroy vital circuits. A necroturret loses one action from its routine for each successful check made to disable it, or two actions on a critical success.</p>","reset":"<p>A necroturret deactivates when it no longer detects living creatures within 120 feet of its location.</p>","routine":"<p>(2 actions) The necroturret uses its actions to attack living creatures with its ice beams. It uses the Lock On reaction once every round to enhance its targeting matrix against the closest living creature. Necroturrets focus on targets trying to disable them.</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Lock On","a":"r","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A living creature moves into a space within 120 feet of the necroturret</p><hr><p><strong>Effect</strong> The necroturret locks on to the closest living creature, granting the necroturret a +1 circumstance bonus to its next attack roll. All living creatures within 10 feet of a necroturret take 1d10+6 cold damage with a DC 20 basic Fortitude save as the turret charges its capacitors. The necroturrets then roll for initiative.</p>"}],"strikeNotes":{"Ice Beam":"<p>Plus Suppressed for 1 round (2 rounds on a critical hit)</p>"}},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/Bv8sq5fogXIQcehn":{"notes":{"hp":"void healing"},"flavor":"<p>Before the end of life on Eox, gefs were a type of domestic animal—a small but robust creature with an enlarged head, sleek quadrupedal body, and fierce loyalty when properly trained. Breeders produced many subspecies of gefs, and they grew in popularity as farm animals, hunting companions, and pets.</p>\n<p>Boutique breeders pioneered genetically engineered hybrid species of gef with folded ears, bizarre fur patterns, and other sought-after features. These gefs were extremely valuable and became popular pets among the upper echelon of elebrians sages, who claimed their pets also had magical properties.</p>\n<p>When elite elebrians sought refuge from the escalating sarcesian conflict, they brought their beloved gefs with them. A few gefs survived in underground bunkers, but living pets fell out of favor once the majority of Eoxians made the transition to undeath. The last living gefs were pampered by their owners for the remainders of their natural lives, allowed a peaceful death, and immediately reanimated as undead creatures to continue providing eternal companionship.</p>\n<p>Phantom gefs are reanimated pets or service animals brought back to unlife by their owners. Most phantom gefs behave similarly to how they did in life. Domesticated gefs retain their training and prefer the company of creatures they bonded with in life. Wild gefs are rare, and are most often strays who form roving packs in the wastelands outside Orphys and elsewhere.</p><h2>Phantom Gef Pets</h2><p>Most phantom gefs are already bonded to an owner—these fiercely loyal creatures would rather die than desert a beloved companion. Feral or stray phantom gefs are elusive and rare, but such creatures can be trained by patient hands. Since phantom gefs behave much as they did when alive, common animal training techniques are useful for coaxing these creatures. However, they're still undead and less interested in food than living animals. The hardest part of taming a phantom gef is spotting one.</p>","abilities":[{"n":"Ghostly Form","a":null,"c":"defensive","t":[],"f":"","d":"<p>A phantom gef is always Concealed. When a phantom gef takes area damage, it's no longer concealed until the beginning of its next turn.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Tug-of-War","a":"1","c":"offensive","t":[],"f":"","d":"<p>The phantom gef attempts to Disarm the target with the following critical success.</p><hr><p><strong>Critical Success</strong> The phantom gef knocks the item out of the creature's hand and into its mouth. While holding the item in this way, the phantom gef can't take any actions except to move, and it can drop the item at any time as a free action.</p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/I4sbG3klcFE1HCMq":{"description":"<p>An ominous ticking and colorful exposed wires hint at the bomb rigged to the shuttle's cockpit.</p>","disable":"<p>DC 16 Thievery to cut the trigger wire, DC 18 Athletics to rip the bomb out of the console and hurl it away from the craft before it explodes, or a Strike against AC 20 to destroy the ignition source before it sets off the explosive charges</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Boom!","a":"r","c":"offensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Someone starts the shuttle engine, or no creatures succeed at their checks to disable the bomb</p><hr><p><strong>Effect</strong> The bomb explodes. All creatures within 30 feet take 6d6 fire damage with a DC 20 basic Reflex save.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/ZK6J3OIVvJVMBEDu":{"description":"<p>A stray shot shatters a window, sucking out the room's precious atmosphere.</p>","disable":"<p>DC 14 Crafting (trained) or DC 14 Labor lore (trained) while adjacent to the window to patch the hole, DC 16 Computers (trained) to activate an emergency metal shutter from any console in the room, or DC 18 Survival or DC 18 Thievery to cover the hole (if adjacent) with a random object as a temporary fix.</p>","reset":"<p>1 minute after a depressurization hazard begins, all air escapes from area F (requiring living creatures to activate their environmental protections or begin suffocating). If the hazard is disabled before 1 minute has passed, this timer resets.</p>","abilities":[{"n":"Blow Out","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A ranged attack critically fails</p><hr><p><strong>Effect</strong> All corporeal creatures inside area <strong>F</strong> are Suppressed until the hazard is disabled or 1 minute has passed.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/zVmwnoVD1jNocpdp":{"flavor":"<p>Reculobutapuses are one of many invasive species from the Vast that hitched a ride into the Pact Worlds and flourished in ecosystems with new food sources and no natural predators. During the Drift Crisis, a Zo! Media crew was stranded in Kazmurg's Absurdity, a relatively uncharted region of space far from the Pact Worlds that can only be explored by studying physical maps. The crew was forced to land on a nearby planet in order to repair their ship and gather the intel necessary to navigate the system.</p>\n<p>Always looking for an angle, the loyal camera crew followed up-and-coming producer Reculo (ambitious male elebrian producer) into the wilderness to document their experiences. Before the producer was swallowed whole, he managed to capture footage of a curious creature—large, flat, and shaped like a mound of dirt and moss with rows of razor-sharp teeth.</p>\n<p>A breeding pair of these ferocious creatures managed to sneak into the ship's cargo hull before the crew departed, or perhaps someone smuggled a specimen aboard to sell back home—nobody knows. The transplanted beasts infested Pact Port's hangars, where they wormed their way onto ships bound for other Pact Worlds.</p>\n<p>The undead of Eox have made the most of their reculobutapus infestation. Once they realized the creatures can be pacified with low jolts of electricity and frequent meals of fresh meat, some necrovites sought after these stylish creatures as pets, prizing them for their ability to change color to match an owner's outfit or home decor—better yet, they provide an extra level of home defense if they aren't fed frequently.</p><h2>Reculobutapus Companions</h2><p>Most consider it dangerous to keep monsters as pets, but a few reckless collectors or nature enthusiasts do it anyway. It's difficult to tame and care for a reculobutapus, which weighs up to 2,100 pounds and needs 20 pounds of fresh meat per day to stay healthy. Hungry reculobutapuses regress quickly, forget their training, and carelessly devour their caregivers. However, undead creatures don't make good meals and can usually heal from a reculobutapus mauling, making the prospect of owning such a dangerous creature less daunting.</p><h2>Designer Pets of the Future?</h2><p>Zo! adopted a litter of reculobutapuses brought in as props for a production. He keeps them as personal pets. Zo! Media funds a breeding project dedicated to breeding a smaller, more docile version of the reculobutapus that could be marketed as a family pet and fashion statement.</p>","abilities":[{"n":"Chameleon Coloration","a":null,"c":"interaction","t":[],"f":"","d":"<p>The reculobutapus changes its coloration to match its surroundings. It doesn't need cover to attempt to Hide with a Stealth check.</p>"},{"n":"Ambush","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A living creature passes within 10 feet of the reculobutapus and has not detected it</p><hr><p><strong>Effect</strong> The reculobutapus Strides directly toward the triggering creature and makes a jaws Strike against it. The target creature is Off-Guard to this attack.</p>"},{"n":"Spiky Hairs","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature within the reculobutapus's reach damages it with an unarmed or non-reach melee Strike</p><hr><p><strong>Effect</strong> Spiky hairs shoot out from the reculobutapus dealing 1d4+3 piercing damage to the creature.</p>"},{"n":"Swallow Whole","a":"1","c":"offensive","t":["attack"],"f":"","d":"<p>Medium, 1d8+3 bludgeoning, Rupture 9</p><hr><p><p>The monster attempts to swallow a creature of the listed size or smaller that it has grabbed or restrained in its jaws or mouth. If a swallowed creature is of the maximum size listed, the monster can't use Swallow Whole again. If the creature is smaller than the maximum, the monster can usually swallow more creatures; the GM determines the maximum. The monster attempts an Athletics vs. Reflex DC check opposed by the grabbed creature's Reflex DC. If it succeeds, it swallows the creature. The monster's mouth or jaws no longer grab a creature it has swallowed, so the monster is free to use them to Strike or Grab once again. The monster can't attack creatures it has swallowed.</p>\n<p>A swallowed creature is Grabbed, is Slowed 1, and has to hold its breath or start suffocating. The swallowed creature takes the listed amount of damage when first swallowed and at the end of each of its turns while it's swallowed. If the victim Escapes this ability's grabbed condition, it exits through the monster's mouth. This frees any other creature grabbed in the monster's mouth or jaws. A swallowed creature can attack the monster that has swallowed it, but only with unarmed attacks or with weapons of light Bulk or less. The swallowing creature is Off-Guard against the attack. If the monster takes piercing or slashing damage equaling or exceeding the listed Rupture value from a single attack or spell, the swallowed creature cuts itself free. A creature that gets free by either Escaping or cutting itself free can immediately breathe and exits the swallowing monster's space.</p>\n<p>Effect: Engulf and Swallow Whole</p>\n<p>If the monster dies, a swallowed creature can be freed by creatures adjacent to the corpse if they spend a combined total of 3 actions cutting the monster open with a weapon or unarmed attack that deals piercing or slashing damage.</p></p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/1RHRano7xlPt44Is":{"description":"<p>Hardlight scamps spawn from this antique projector and harass nearby living creatures.</p>","disable":"<p>DC 20 Arcana (trained) to depower the magical circuits, DC 20 Computers (trained) to reprogram the projector, or DC 20 Athletics (trained) to rip the projector out of the wall.</p>","reset":"<p>The trap deactivates after 6 rounds and resets after 1 hour.</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Generate Scamp","a":"f","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> Two or more living creatures enter area <strong>A5</strong></p><hr><p><strong>Effect</strong> The projector creates two hardlight scamps next to the podium. This projector can manifest only two scamps at a time. The scamps roll initiative. The scamps disappear when slain, or if their projector is deactivated or destroyed.</p>"},{"n":"Infuse Scamp","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A hardlight scamp is critically hit but not destroyed</p><hr><p><strong>Effect</strong> The affected hardlight scamp regains 1d8 healing Hit Points.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/HOgqslwrHCeXlYp8":{"gear":["Integrated Shield"],"notes":{"hp":"void healing","ac":"12 when broken"},"flavor":"<p>Rigor mortics were designed as literal cannon fodder for Corpse Fleet squadrons performing boarding actions in deep space. Barrow's notorious research and development division engineered these unliving weapons from the recycled remnants of heavily damaged troopers that were then grafted into powered armor. Rigor mortics are ammunition and shock trooper combined, designed to blast through hulls or crash-land into planets—and keep fighting without falling apart on impact.</p><h2>Forging a Rigor Mortic</h2><p>Rigor mortics are built from chunks of soldiers left behind on the battlefield, grafted into heavy armor and reanimated by necromagitech. Some rigor mortics are forged from the corpses of Corpse Fleet heroes whose bodies are too broken to continue fighting, but most are amalgams of Corpse Fleet survivors, dead enemies, and living conscripts cruelly forced to endure this fate. Once a collection of parts is grafted permanently into a suit of armor, the final step is coating the rigor mortic in a shell of supernatural ice, turning them into projectiles that can be fired from starship cannons in squads of two to four per shot. These \"rigor mortars,\" as they've been nicknamed by some fleet captains, are stored in cryohangars until the moment they're loaded into a cannon. The ice melts away during the rigor mortic's flight, releasing the thawed undead from their shell.</p>","abilities":[{"n":"Breaching Strikes","a":null,"c":"defensive","t":[],"f":"","d":"<p>A rigor mortic's melee Strikes treats the Hardness of all other creatures and objects as though they were 5 less than their normal value.</p>"},{"n":"Cocoon Projectile","a":null,"c":"defensive","t":[],"f":"","d":"<p>A fully-encased rigor mortic can be fired from a starship weapon into another vehicle or from a starship onto the ground. When delivered onto a battlefield in this fashion, the rigor mortic ignores all falling damage even if they're dropped from orbit. For 1 hour after a drop, a rigor mortic rolls initiative with a –2 penalty and is Stunned 1 for the first round of combat.</p>"},{"n":"Construct Armor","a":null,"c":"defensive","t":[],"f":"","d":"<p>A rigor mortic's grafted armor plates give it Hardness. This Hardness reduces any damage it takes by an amount equal to its Hardness. Once the rigor mortic is reduced to less than half its Hit Points, or immediately upon being damaged by a critical hit, its construct armor breaks, removing its Hardness and reducing its Armor Class to 12.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Breaching Charge","a":"2","c":"offensive","t":[],"f":"","d":"<p>The rigor-mortic Strides twice and Strikes. If the Strike is a critical hit with a breaching weapon, the target is Stunned 1.</p>"},{"n":"Construct Shield","a":null,"c":"offensive","t":[],"f":"","d":"<p>A rigor mortic can Raise a Shield using its integrated armor.</p>"},{"n":"Slow March","a":"2","c":"offensive","t":[],"f":"","d":"<p>The rigor mortic Raises a Shield and Strides twice. The rigor mortic's allies within 20 feet gain lesser cover.</p>\n<p>Effect: Cover</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/aONi4XH2mT0qWuzB":{"lang":["Common","Eoxian","Necril","Sarcesian"],"lore":[["Corpse Fleet Lore",15]],"gear":["Phase Cutlass","Broken Tactical Dueling Sword"],"notes":{"hp":"void healing"},"abilities":[{"n":"Lonely Rage","a":null,"c":"defensive","t":[],"f":"","d":"<p>Sanimus is an even more aggressive combatant when he's forced to fight alone. When fighting with no active allies, he flies into a rage that gives him an additional reaction at the start of each turn.</p>"},{"n":"Reactive Strike","a":"r","c":"defensive","t":[],"f":"","d":"<p><p><strong>Trigger</strong> A creature within the monster's reach uses a manipulate action or a move action, makes a ranged attack, or leaves a square during a move action it's using.</p>\n<hr>\n<p><strong>Effect</strong> The monster attempts a melee Strike against the triggering creature. If the attack is a critical hit and the trigger was a manipulate action, the monster disrupts that action. This Strike doesn't count toward the monster's multiple attack penalty, and its multiple attack penalty doesn't apply to this Strike.</p></p>"},{"n":"Vengeful Strike","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature within Sanimus's first range increment uses an action or reaction to heal, grant bonuses, or otherwise assist another creature</p><hr><p><strong>Effect</strong> Sanimus makes a ranged Strike against the triggering creature.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Auto-Fire","a":"2","c":"offensive","t":[],"f":"","d":"<p><strong>Minigun</strong> (60-foot cone, analog, automatic, magical, unholy)</p>\n<p><strong>Damage</strong> 2d10+8 piercing (DC 20 basic Reflex)</p>"},{"n":"Concussive Feint","a":"1","c":"offensive","t":[],"f":"","d":"<p><strong>Requirements</strong> Sanimus is holding his minigun</p><hr><p><strong>Effect</strong> Sanimus attempts an Intimidation vs. Perception DC check against a single target's Perception DC within the first range increment of his minigun. On a success, the target counts as Clumsy 2 against his next area attack before the end of his current turn. On a critical success, the target is clumsy 2 against all of his area attacks until the end of his next turn.</p>"},{"n":"Crescent Blast","a":"2","c":"offensive","t":["flourish"],"f":"","d":"<p>Sanimus twists his minigun while firing it, curving its bullets through the air. He makes a ranged Strike or Auto-Fire attack with his minigun but calculates the point of origin for the attack as though it originated from up to 2 squares outside of his current space on the map, allowing him to fire his weapon around cover and corners.</p>"},{"n":"Infuse Weapon","a":null,"c":"offensive","t":["divine"],"f":"","d":"<p>Sanimus's weapons are infused with his hatred, gaining the magical and unholy traits and dealing spirit damage when he wields them. These weapons deal an additional 1d8 spirit damage to living and undead creatures.</p>"},{"n":"Minigun Training","a":null,"c":"offensive","t":[],"f":"","d":"<p>Sanimus has trained for centuries with his minigun and can push his gear beyond what the living can achieve. When using the Auto-Fire action, Sanimus can target all creatures within the first full range increment of his weapon, rather than just half of its range. Additionally, Sanimus can ignore any number of creatures in this area without penalty. Finally, his minigun only needs to be reloaded once per day in a special unholy ritual during his daily preparations.</p>"},{"n":"Suppressing Fire","a":null,"c":"offensive","t":[],"f":"","d":"<p>Enemies that fail their save against Sanimus's Auto-Fire attacks become Suppressed until the start of his next turn.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/JWj8jwhBc13XUgrP":{"abilities":[{"n":"Radio Silence","a":null,"c":"defensive","t":["aura"],"f":"","d":"<p>60 feet. Non-allied comm units and other tech-based forms of communication don't function within the aircraft's aura unless its operator succeeds at a Computers check versus the scout drone's Stealth DC as an Interact action.</p>"},{"n":"Attack Pattern Beta","a":"2","c":"offensive","t":[],"f":"","d":"<p>The drone makes a Strike against one target, then Steps or Strides, and then makes a Strike against one target, which can be the same as or different than the initial target. Both Strikes count toward its multiple attack penalty, but its multiple attack penalty doesn't increase until after it makes both Strikes.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/QgcpbGsOgx3Vh8iV":{"lang":["Eoxian"],"notes":{"per":"metal sense (30 feet)"},"abilities":[{"n":"Dangerous Recycling","a":null,"c":"interaction","t":[],"f":"","d":"<p>Over the course of 1 minute of uninterrupted work, a scrap rat can assemble any level 0 commercial grenade using nothing but junk. It falls apart and becomes unusable junk after 10 minutes.</p>"},{"n":"Metal Sense","a":null,"c":"interaction","t":[],"f":"","d":"<p>A scrap rat visionary can sense metal objects within 30 feet as a precise sense, including items hidden by illusions such as Invisibility.</p>"},{"n":"Constant Spells","a":null,"c":"interaction","t":[],"f":"","d":"<p><p>A constant spell affects the monster without the monster needing to cast it, and its duration is unlimited. If a constant spell gets counteracted, the monster can reactivate it by spending the normal spellcasting actions the spell requires.</p></p>"},{"n":"Scoring","a":null,"c":"offensive","t":[],"f":"","d":"<p>When the scrap rat's tail deals damage to an object or creature with the tech trait, the tail also gains the following traits until the beginning of the scrap rat's next turn: deadly (1d4), hampering, and razing.</p>"},{"n":"Scrap Spray","a":"2","c":"offensive","t":[],"f":"","d":"<p>The scrap rat visionary fires jagged junk shards at multiple enemies. All creatures in a 20-foot cone must attempt a DC 18 basic Reflex save or take 3d6 piercing damage. On a critical failure, the creature is Suppressed until the end of the scrap rat visionary's next turn.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/QPmLfay4U6Rd9fWl":{"description":"<p>A large 5-foot-high pile of junk towers above the ground with holes in it big enough for only rats to squeeze through.</p>","disable":"<p>DC 12 Thievery to stabilize the junk pile, DC 14 Survival to collapse it down on itself, or DC 16 Athletics to smash through it without setting it off</p>","abilities":[{"n":"Spiky Collapse","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature other than a scrap rat enters the area of the junk warren</p><hr><p><strong>Effect</strong> The warren collapses in on the creature, making a melee strike with an attack modifier of +5. If the trap was undetected, the creature is Off-Guard against this attack.</p><hr><p><strong>Critical Success</strong> The creature takes double damage and gains the Restrained condition until the end of its next turn (Escape).</p>\n<p><strong>Success</strong> The creature takes 1d6 piercing damage and gains the Grabbed condition until the end of its next turn (Escape).</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/c5ryR23ymRbukIgd":{"description":"<p>A tight grid of ionized particles crisscrosses the door into the computer center, hissing audibly and glowing bright blue.</p>","disable":"<p>DC 19 Computers or DC 19 Physical science lore to disable the shock grid through the keypad, or DC 21 Crafting or DC 21 Thievery to short-circuit the wires along the grid's perimeter</p>","reset":"<p>The trap resets automatically until disabled or until it can no longer detect any living creatures within 10 feet of the door outside in area <strong>E2</strong>.</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Shocking!","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A living creature fails their check to disable the shock grid or walks through the shock grid</p><hr><p><strong>Effect</strong> The triggering creature takes 4d8+10 electricity damage with a DC 21 basic Fortitude save.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/H8QkiU5XVdCj8zZs":{"description":"<p>A misshapen blob of pastry and magic wobbles as it keeps rising beyond normal baked good dimensions.</p>","disable":"<p>DC 18 Cooking lore (trained), DC 18 Survival (trained), or DC 18 Thievery (trained) to gently deflate the soufflé, or DC 23 Athletics to beat the soufflé into submission</p>","routine":"<p>(3 actions) The souffle Rises.</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Sudden Rise","a":"r","c":"offensive","t":["fire","nonlethal"],"f":"","d":"<p><strong>Trigger</strong> Zo!'s sabotage begins</p><hr><p><strong>Effect</strong> all creatures adjacent to a souffle take 2d6 fire damage with a DC 23 basic Reflex save. On a critical failure, the creature is also Suppressed.</p>"},{"n":"Rise","a":"3","c":"offensive","t":[],"f":"","d":"<p>The souffle expands to fill a 10-foot burst centered on the cooking station. Each additional round, the souffle grows to fill all adjacent squares that are touching it. Creatures in these squares are affected by Sudden Rise.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/6CBtaIhJZdAgAqVf":{"description":"<p>These three treadmills' rotating belts are no longer locked in place and now spin freely when activated.</p>","disable":"<p>DC 13 Sports lore to remember that older models of treadmills have an emergency brake that can be activated with a pull string, DC 15 Thievery to jam the mechanism, or DC 17 Crafting to improvise a stop for the rotating belts</p>","reset":"<p>The trap resets automatically until disabled.</p>","stealthNote":"<p>(trained)</p>","abilities":[{"n":"Spin-Off","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature steps on the treadmill</p><hr><p><strong>Effect</strong> The creature must attempt a DC 15 Reflex save.</p><hr><p><strong>Critical Success</strong> The creature is unaffected.</p>\n<p><strong>Success</strong> The creature is pushed back 5 feet.</p>\n<p><strong>Failure</strong> The creature is knocked Prone and pushed back 5 feet.</p>\n<p><strong>Critical Failure</strong> The creature is knocked prone, takes 1d6 bludgeoning damage, and is pushed back 10 feet. If this forced movement would have the PC impact another creature, that subsequent creature must succeed at a DC 15 Reflex save or be knocked prone.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/YLo7jNSMWVP9skOm":{"lang":["Common","Vesk"],"lore":[["Warfare Lore",6]],"gear":["Doshko","Flamethrower","Veskarium Imperial Plate","Chem Tank (Commercial) (2)"],"abilities":[{"n":"Quick Step","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> A creature within the paratrooper’s reach leaves a square during a move action it’s using</p><hr><p><strong>Effect</strong> The paratrooper Steps twice.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/6r1fVn61okoxeQ1Q":{"lang":["Eoxian","Necril"],"lore":[["Corpse Fleet Lore",9]],"gear":["Tactical Needler Pistol","Armored Lab Coat","Projectile Ammo (6)"],"notes":{"hp":"corrupting blood, void healing"},"abilities":[{"n":"Grave Weapon","a":null,"c":"interaction","t":[],"f":"","d":"<p>The wight scientist is bound to a needler pistol it used in life.</p>"},{"n":"Corrupting Influence","a":null,"c":"defensive","t":[],"f":"","d":"<p>Any time a living creature loses Hit Points due to Corrupting Blood, the wight scientist gains 3 temporary Hit Points.</p>"},{"n":"Reciprocal Strike","a":"r","c":"defensive","t":[],"f":"","d":"<p><strong>Trigger</strong> The wight scientist is reduced to 0 Hit Points</p><hr><p><strong>Effect</strong> The wight scientist makes a melee or ranged Strike before being destroyed. Corrupting Influence does not apply to this Strike.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Corrupting Blood","a":null,"c":"offensive","t":["curse","injury","poison","void"],"f":"","d":"<p>The wight scientist's unarmed attacks and bound weapons inflict a curse that makes a creature grow weak and corrupted by gruesome impulses.</p>\n<p><strong>Saving Throw</strong> DC 18 Fortitude</p>\n<p><strong>Maximum Duration</strong> 5 rounds</p>\n<p><strong>Stage 1</strong> 1d4 void damage and Sickened 1 (1 round)</p>\n<p><strong>Stage 2</strong> 1d6 void damage and Sickened 2 (1 round)</p>\n<p><strong>Stage 3</strong> 1d8 void damage, Sickened 3, and Confused (1 round)</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/UuRslEeJPQaLc1Fq":{"notes":{"hp":"fast healing 1, void healing","per":"darkvision"},"flavor":"<p>Eons ago, the planet of Eox was a living, breathing world. Though its current necrovite rulers don't care to record the myriad of lifeforms that once flourished there, Eox once hosted countless species of wildlife. Most of these creatures died in the cataclysm that ruined the planet, but some have managed to make the transition to undeath in the time since.</p>\n<p>Xoalats were once the most popular livestock animals on the continent of Atraskia. Vast ranches farmed these animals in a coastal plains region now known as the Atraskian Shelf. With a single horn and sturdy frame, mature xoalat hides grew into thick braids of hair in many colors that ranchers would harvest for textiles. Xoalats thrive in most environments from arid plains to arctic tundra and consume less feed than typical livestock, as they spend their time rooting in the ground for bugs, weeds, and roots.</p>\n<p>Every living xoalat perished after the Death Wail rebounded at Eox, but some returned as undead creatures afterward, either woken by undead ranchers or reanimated by ambient necromantic processes. Today, all remaining xoalats are undead, and only a few elebrians own rare items woven from xoalat mane that were passed down through their families for many generations. Rarely, elebrians have allowed these precious heirlooms to be examined by scientists, giving the galaxy the first glimpse of the beauty of xoalat mane textiles in centuries.</p>\n<p>Xoalats have adapted to the strange necrotic ecosystem that has taken over the Eoxian wilderness. Scientists and sages are baffled by the resurgence of unlife outside the necropolises, where bone sages have carefully cultivate undead ecologies controlled by magic. Only a few secretive Xenowardens have managed to study these blighted environments.</p>\n<p>As herd animals, xoalats are usually docile, but they can be spooked by the presence of living creatures. When panicked, a xoalat tries to escape to open ground but violently lashes out at anyone or anything in their path to safety.</p><h2>Xoalat Husbandry</h2><p>Undead xoalats have developed the ability to slowly regenerate their bones, marrow, and leathery hides. Instead of cloth and textiles, modern xoalat ranchers harvest samples of bone marrow and hide from their regenerating herds. These materials are valuable to necrograft manufacturers and medical technology companies all over Eox.</p><h2>Xoalat Behavior</h2><p>Xenowardens who have studied these pitiful creatures are fascinated by their behavior, which seems to consist of repetitive loops that mimic the activities of living xoalats. Frequently observed behaviors include rooting around in the dead Eoxian soil even though they don't need to eat, grazing and roaming in herds, and making a loud mewling sound. Xoalats are generally timid unless spooked, but respond well to undead ranchers.</p>","abilities":[{"n":"Fast Healing 1","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A monster with this ability regains the given number of Hit Points each round at the beginning of its turn.</p></p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Ferocious Charge","a":"2","c":"offensive","t":[],"f":"","d":"<p>The xoalat Strides up to twice its Speed. If it ends its movement within melee reach of a target, it can make a horn Strike against that target. If the xoalat critically hits with this Strike, the creature hit is knocked back 10 feet.</p>"},{"n":"Trample","a":"3","c":"offensive","t":[],"f":"","d":"<p>medium or smaller, hoof, DC 14 basic Reflex</p><hr><p><p>The monster Strides up to double its Speed and can move through the spaces of creatures of the listed size, Trampling each creature whose space it enters. The monster can attempt to Trample the same creature only once in a single use of Trample. The monster deals the damage of the listed Strike, but trampled creatures can attempt a basic Reflex save at the listed DC (no damage on a critical success, half damage on a success, double damage on a critical failure).</p></p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/WOH7D2wZcemQrT8V":{"lang":["True linguist"],"lore":[["Media Lore",37]],"gear":["Ivory Chompers","Zo!'s Microphone","Second Skin","Holoskin (Tactical)"],"notes":{"hp":"void healing"},"abilities":[{"n":"Media Lore","a":null,"c":"interaction","t":[],"f":"","d":"<p>Zo! can use Media Lore to Recall Knowledge about any topic.</p>"},{"n":"True Linguist","a":null,"c":"interaction","t":[],"f":"","d":"<p>Zo! has enchanted himself with the ability to speak and understand all languages, giving him the permanent effects of the Truespeech spell.</p>"},{"n":"Change the Channel","a":"r","c":"defensive","t":["misfortune"],"f":"","d":"<p><strong>Trigger</strong> Zo! is targeted by a creature or weapon with the tech trait</p><hr><p><strong>Effect</strong> Zo! uses a universal remote implanted in his forefinger to take control of the incoming assault and redirect it toward a new target of Zo!'s choice, forcing the attacker to resolve their attack against this new target, if there's one within range. If there are no available targets, the attacker resolves their attack against Zo! but must roll their attack twice and use the worse result. Once a creature or weapon has been targeted by this ability, it's immune to Change the Channel for 24 hours.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Ad Break","a":"1","c":"offensive","t":["auditory","concentrate","mental"],"f":"","d":"<p>Zo! broadcasts loud chatter and jingles from countless advertisements for upcoming shows and brand-new products. Zo! attempts a Performance vs. Will DC check against the target creature's Will DC. On a success, the target takes a –1 status penalty to any action it takes that has the concentrate trait (rolls and DCs) until the end of Zo!'s next turn. On a critical success, this penalty increases to –2.</p>"},{"n":"Cut!","a":"f","c":"offensive","t":["arcane"],"f":"once per hour","d":"<p><strong>Frequency</strong> once per hour</p>\n<p><strong>Trigger</strong> An enemy creature uses a reaction against Zo!</p><hr><p><strong>Effect</strong> Zo! expends a spell slot with a rank equal to half the triggering creature's level (round down) to create a magical freeze frame. The triggering reaction is disrupted.</p>"},{"n":"Media Magic","a":"2","c":"offensive","t":["arcane","emotion","illusion","incapacitation","manipulate","mental"],"f":"","d":"<p>Zo! conjures an illusory scene showing off unaired footage from a controversial show or teasers for an upcoming production. All creatures within a 20-foot emanation must attempt a DC 41 Will save. A creature that succeeds is then temporarily immune to Media Magic for 1 hour.</p><hr><p><strong>Critical Success</strong> The creature is unaffected.</p>\n<p><strong>Success</strong> The creature is Fascinated until the start of Zo!'s next turn.</p>\n<p><strong>Failure</strong> The creature is fascinated with Zo! until the beginning of Zo!'s next turn. If the fascinated creature is adjacent to Zo!, it stays still and can't take actions. If the creature is attacked, the fascination ends.</p>\n<p><strong>Critical Failure</strong> As failure. In addition, the creature is Suppressed 1 minute.</p>"}]},"sf2e-anachronism.guilt-of-the-grave-world-bestiary/iv2NsIIE0wUX5Ktr":{"notes":{"hp":"void healing"},"abilities":[{"n":"Slow","a":null,"c":"interaction","t":[],"f":"","d":"<p>A zombie is permanently Slowed 1 and can't use reactions.</p>"},{"n":"Void Healing","a":null,"c":"defensive","t":[],"f":"","d":"<p><p>A creature with void healing draws health from void energy rather than vitality energy. It is damaged by vitality damage and is not healed by vitality healing effects. It does not take void damage, and it is healed by void effects that heal undead.</p></p>"},{"n":"Grab","a":"1","c":"offensive","t":[],"f":"","d":"<p><p><strong>Requirements</strong> The monster's last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr><p><strong>Effect</strong> If used after a Strike, the monster attempts to Grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature's multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it's grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster's next turn.</p></p>"}],"strikeNotes":{"Jaws":"<p><strong>Requirements</strong> The zombie has a creature Grabbed or Restrained.</p>"}}});
